output-contract.example:
{
  "artefact_id": "eh-example-001",
  "owner": "alex@acme.com",
  "decision": "see templates/error-handling.md for shape",
  "rationale": "Decision cites input artefact A (URL) and input artefact B (path). The rationale is at least two sentences and identifies which constraints drove the call.",
  "inputs_used": [
    {
      "name": "A",
      "source": "https://example.com/A"
    },
    {
      "name": "B",
      "source": "repo:path/B"
    }
  ],
  "version": "1.0.0",
  "last_reviewed": "2026-05-23"
}

example.code:
HTTP/1.1 400 Bad Request
Content-Type: application/problem+json

{
  "type": "https://api.example.com/errors/validation-error",
  "title": "Validation Error",
  "status": 400,
  "detail": "Request validation failed",
  "instance": "/users",
  "traceId": "00-4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-01",
  "errors": [
    {"field": "email", "code": "format", "message": "must be a valid e-mail address"}
  ]
}
